  --page-padding: 20px;
  --side-panel-width: 340px;
  --video-max-width: 1500px;

  /* Surface colors */
  --color-surface-page: #535370;
  --color-surface-panel: #16162a;
  --color-surface-elevated: #252540;
  --color-surface-control: #202039;
  --color-surface-panel-hover: #2a2a48;

