  --color-text-primary: #eeeeee;
  --color-text-secondary: #d2d7ed;
  --color-text-muted: #9ca3af;
  --color-text-soft: #cccccc;

  /* Border colors */
  --color-border-default: #444444;
  --color-border-strong: #555555;
  --color-border-subtle: #333333;

  /* Brand / accent colors */
  --color-brand-primary: #9147ff;
  --color-brand-secondary: #5865f2;
  --color-brand-soft: rgba(145, 71, 255, 0.35);
  --color-brand-ring: rgba(145, 71, 255, 0.4);
  --color-brand-ring-soft: rgba(145, 71, 255, 0.18);

  /* Semantic state colors */
  --color-state-success: #55aa88;
  --color-state-success-strong: #44aa77;
  --color-state-success-soft: #99ffdd;
  --color-state-success-shadow: rgba(90, 170, 136, 0.4);
  --color-state-danger: #ee6666;
  --color-state-danger-strong: #cc0000;
  --color-state-info: rgba(160, 190, 255, 0.9);
  --color-state-info-soft: #a9b3ff;
  --color-state-info-muted: #c8d0ff;
  --color-state-warning-bg: rgba(180, 120, 40, 0.18);
  --color-state-warning-border: rgba(255, 200, 100, 0.42);
  --color-state-warning-text: #f5e6c8;

  /* Media / action-specific colors */
  --color-action-ptt-border: rgba(255, 160, 80, 0.6);
  --color-action-ptt-bg-active: rgba(255, 160, 80, 0.35);
  --color-action-ptt-border-active: rgba(255, 190, 120, 0.85);

  /* Base / utility colors */
  --color-black: #000000;
  --color-white: #ffffff;
  --color-overlay-strong: rgba(0, 0, 0, 0.75);
  --color-overlay-soft: rgba(255, 255, 255, 0.1);
  --color-overlay-subtle: rgba(0, 0, 0, 0.15);
  --color-glass-border-soft: rgba(255, 255, 255, 0.05);
  --color-glass-border: rgba(255, 255, 255, 0.12);
  --color-glass-border-strong: rgba(255, 255, 255, 0.2);
  --color-glass-bg-subtle: rgba(255, 255, 255, 0.03);
  --color-glass-bg-soft: rgba(255, 255, 255, 0.06);
  --color-glass-bg: rgba(255, 255, 255, 0.08);
  --color-panel-shadow: rgba(0, 0, 0, 0.45);
  --color-panel-shadow-strong: rgba(0, 0, 0, 0.5);
  --color-focus-ring: rgba(120, 180, 255, 0.8);
  --color-focus-border: rgba(120, 180, 255, 0.7);
  --color-focus-border-soft: rgba(120, 180, 255, 0.5);

  /* Backward-compatible aliases (gradual migration) */
  --color-bg-main: var(--color-surface-page);
  --color-bg-panel: var(--color-surface-panel);
  --color-bg-elevated: var(--color-surface-elevated);
  --color-bg-control: var(--color-surface-control);
  --color-bg-panel-hover: var(--color-surface-panel-hover);
  --color-border: var(--color-border-default);
  --color-accent: var(--color-brand-primary);
  --color-accent-2: var(--color-brand-secondary);
  --color-accent-soft: var(--color-brand-soft);
  --color-accent-ring: var(--color-brand-ring);
  --color-accent-ring-soft: var(--color-brand-ring-soft);
  --color-success: var(--color-state-success);
  --color-success-strong: var(--color-state-success-strong);
  --color-success-soft: var(--color-state-success-soft);
  --color-success-shadow: var(--color-state-success-shadow);
  --color-danger: var(--color-state-danger);
  --color-danger-strong: var(--color-state-danger-strong);
  --color-info: var(--color-state-info);
  --color-info-soft: var(--color-state-info-soft);
  --color-info-muted: var(--color-state-info-muted);
  --color-warning-bg: var(--color-state-warning-bg);
  --color-warning-border: var(--color-state-warning-border);
  --color-warning-text: var(--color-state-warning-text);
  --color-ptt-border: var(--color-action-ptt-border);
  --color-ptt-bg-active: var(--color-action-ptt-bg-active);
  --color-ptt-border-active: var(--color-action-ptt-border-active);

  --bg-main: #535370;
  --bg-panel: #16162a;
  --bg-elevated: #252540;

  --border-color: #444;
  --border-color-strong: #555;

  --breakpoint-side: 900px;
  --breakpoint-narrow: 600px;
}

html {
  height: 100%;
  overflow-x: hidden;
}

body {
  margin: 0;
  min-height: 100%;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--color-text-primary);
  overflow-x: hidden;
  -webkit-tap-highlight-color: transparent;
}

#root {
  min-height: 100vh;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}
