/* Root Layout                   */
/* ============================= */

.roomPage--b4pEB {
  /* padding: var(--page-padding); */
  min-height: 100vh;
  background: var(--bg-main);
  box-sizing: border-box;
}

.layoutRoot--FvcuA {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 8px;
  height: 100%;
  position: relative;
  background: var(--bg-main);
}


/* ============================= */
/* Top bar                       */
/* ============================= */

.topBar--wDF7c {
  display: flex;
  align-items: center;

  flex-shrink: 0;
}


/* ============================= */
/* Main content                  */
/* ============================= */

.mainArea--XnC1v {
  display: flex;
  gap: 8px;

  flex: 1 1 auto;

  min-height: 0;

  align-items: stretch;
}


/* ============================= */
/* Video section                 */
/* ============================= */

.videoArea--_8sAR {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  /* align-items: center; */
}

.videoArea--_8sAR > * {
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  /* Плеер заполняет колонку; ограничение по ширине убрано для immersive-layout */
  max-width: var(--video-max-width);
}

/* ============================= */
/* Side panel (chat)             */
/* ============================= */

.sidePanel--yuMZl {
  flex: 0 0 var(--side-panel-width);

  width: var(--side-panel-width);
  max-width: var(--side-panel-width);

  min-height: 0;

  display: flex;
  flex-direction: column;

  background: var(--bg-panel);

  border-radius: 12px;
  border: 1px solid var(--border-color);
}


.sidePanel--yuMZl > * {
  flex: 1;

  display: flex;
  flex-direction: column;

  min-height: 0;
}


.sidePanel--yuMZl .messages {
  flex: 1;
  overflow: auto;
}


/* ============================= */
/* Bottom panel (controls)       */
/* ============================= */

.bottomPanel--eE3o6 {
  background: var(--bg-panel);

  border-radius: 12px;
  border: 1px solid var(--border-color);

  flex-shrink: 0;
}


/* ============================= */
/* Overlay                       */
/* ============================= */

.overlay--jaiTh {
  position: absolute;
  inset: 0;

  pointer-events: none;
}

.overlay--jaiTh * {
  pointer-events: auto;
}


/* ============================= */
/* Devtools                      */
/* ============================= */

.devtools--Knx8Q {
  max-height: 200px;
  overflow: auto;
}

.devtools-output {
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--color-border);
  background: var(--color-bg-panel);
  color: var(--color-text-primary);
  font-size: 13px;
}

.devtools-output p {
  margin: 0 0 6px;
}

.devtools-output button,
.devtools-disable,
.devtools-enable {
  margin-left: 6px;
  padding: 4px 8px;
  font-size: 12px;
  border-radius: 8px;
  border: 1px solid var(--color-border-strong);
  background: var(--color-bg-elevated);
  color: var(--color-text-primary);
  cursor: pointer;
}

.devtools-output button:hover,
.devtools-disable:hover,
.devtools-enable:hover {
  background: var(--color-overlay-soft);
}


/* ============================= */
/* Responsive                    */
/* ============================= */

@media (max-width: 900px) {

  .mainArea--XnC1v {
    flex-direction: column;
  }

  .videoArea--_8sAR {
    flex: 1 1 auto;
  }

  .sidePanel--yuMZl {
    flex: 0 0 auto;

    width: 100%;
    max-width: 100%;

    height: 320px;
  }

}


@media (max-width: 600px) {

  .roomPage--b4pEB {
    padding: 10px;
  }

  .topBar--wDF7c {
    border-radius: 10px;
  }

  .videoArea--_8sAR {
    flex: 1 1 auto;
    border-radius: 10px;
  }

  .sidePanel--yuMZl {
    height: 260px;
  }

}
