/**
 * Client-side runtime event logger. Subscribes to key GRS events for debugging.
 *
 * Уровень логирования (localStorage, до `attachRuntimeLogger`):
 * - `GRS_RUNTIME_LOG` = `off` | `0` — не подписываться вообще.
 * - `GRS_RUNTIME_LOG` = `all` | `verbose` — все события из списка, включая частые stream:*.
 * - иначе — «тихий» режим: без `stream:created` / `stream:processing` / `stream:processed` (меньше шума в консоли).
 *
 * Примечание: шум от повторных `stream:created` также снижен стабильными `id` в publish (peer-bootstrap, video-stream, screen share).
 */
import { resolveRuntimeLogEvents } from "@grstream/core";
const LOG_PREFIX = "[GRS]";
const TRUNCATE_KEYS = new Set([
    "token",
    "url",
    "pastedAnswer",
    "pastedInvite",
    "inviteToken",
    "answer",
]);
/** Avoid multi‑KB console lines for invite/URL payloads (shallow only). */
function sanitizeLogPayload(payload) {
    if (payload === null || payload === undefined)
        return payload;
    if (typeof payload !== "object" || Array.isArray(payload))
        return payload;
    const o = payload;
    let changed = false;
    const out = { ...o };
    for (const key of TRUNCATE_KEYS) {
        const v = out[key];
        if (typeof v === "string" && v.length > 160) {
            out[key] = `[omitted ${v.length} chars]`;
            changed = true;
        }
    }
    return changed ? out : payload;
}
function resolveEventsToSubscribe() {
    return resolveRuntimeLogEvents();
}
export function attachRuntimeLogger(runtime) {
    const names = resolveEventsToSubscribe();
    if (names.length === 0) {
        return () => { };
    }
    const unsubs = names.map((event) => runtime.events.on(event, (payload) => {
        if (typeof console?.log === "function") {
            const safe = payload !== undefined ? sanitizeLogPayload(payload) : "";
            console.log(`${LOG_PREFIX} ${event}`, safe);
        }
    }));
    return () => unsubs.forEach((off) => off());
}
