const ROOM_KEYS = ["room", "roomId"];
const SIGNAL_KEYS = ["signaling", "endpoint", "ws", "sig"];
export function parseLobbyDeepLink(search) {
    const params = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
    let roomId = "";
    for (const k of ROOM_KEYS) {
        const v = params.get(k)?.trim();
        if (v) {
            roomId = v;
            break;
        }
    }
    let signaling = "";
    for (const k of SIGNAL_KEYS) {
        const v = params.get(k)?.trim();
        if (v) {
            signaling = v;
            break;
        }
    }
    const aj = params.get("autojoin") ?? params.get("join");
    const autojoin = aj === "1" || aj === "true" || aj === "yes";
    if (!roomId && !signaling)
        return null;
    return { ...(roomId ? { roomId } : {}), ...(signaling ? { signaling } : {}), autojoin };
}
/** Сборка ссылки для гостя (тот же деплой, что и страница). */
export function buildLobbyGuestUrl(opts) {
    const base = opts.baseUrl.trim() || (typeof window !== "undefined" ? window.location.origin + window.location.pathname : "/");
    const u = new URL(base, typeof window !== "undefined" ? window.location.origin : "http://localhost/");
    u.searchParams.set("room", opts.roomId);
    u.searchParams.set("signaling", opts.signaling);
    if (opts.autojoin !== false) {
        u.searchParams.set("autojoin", "1");
    }
    return u.toString();
}
