import { extractInviteLzToken, notifyRoomUrlSync } from "@grstream/room-core";
/** Берёт первую осмысленную строку: URL, строка с invite/hash, иначе первая непустая. */
export function extractInviteSourceFromFileText(text) {
    const lines = text
        .split(/\r?\n/)
        .map((l) => l.trim())
        .filter((l) => l.length > 0);
    for (const line of lines) {
        if (/^https?:\/\//i.test(line))
            return line;
    }
    for (const line of lines) {
        if (line.includes("#o=") || line.includes("?invite=") || line.includes("&invite="))
            return line;
    }
    return lines[0] ?? text.trim();
}
/**
 * Применяет содержимое файла как открытие ссылки-приглашения (тот же эффект, что вставка URL в адресную строку).
 */
export function applyInviteFromFileContent(text) {
    if (typeof window === "undefined")
        return { ok: false, message: "Недоступно в этой среде" };
    const source = extractInviteSourceFromFileText(text);
    if (!source)
        return { ok: false, message: "В файле нет текста" };
    try {
        if (/^https?:\/\//i.test(source)) {
            const u = new URL(source);
            if (u.origin === window.location.origin) {
                window.history.replaceState(null, "", u.pathname + u.search + u.hash);
                notifyRoomUrlSync();
                return { ok: true };
            }
            window.location.assign(source);
            return { ok: true };
        }
        const token = extractInviteLzToken(source);
        if (!token)
            return { ok: false, message: "Не удалось разобрать приглашение" };
        const path = window.location.pathname || "/";
        const search = window.location.search || "";
        window.history.replaceState(null, "", `${path}${search}#o=${token}`);
        notifyRoomUrlSync();
        return { ok: true };
    }
    catch {
        return { ok: false, message: "Неверный формат ссылки" };
    }
}
